/* ШТРИХКОДЫ, ЭТИКЕТКИ И ЦЕННИКИ.
   1) Штрихкод картинкой SVG рядом с каждой выделенной клеткой: EAN-13, EAN-8, Code 128,
      DataMatrix (и DataMatrix GS1 для маркировки). Кодировщики — внутри плагина.
   2) Этикетки и ценники для листов с наклейками: таблица товаров → на пустом листе сетка
      этикеток точно по размеру наклеек, с названием, ценой и штрихкодом; плагин сам
      ставит параметры печати (A4, книжная, масштаб 100%, без полей и сетки). */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* ===== Штрихкоды: EAN-13, EAN-8, Code 128, DataMatrix (ECC 200) — всё внутри плагина =====
   Выход — полоски ('1' — чёрный модуль) или матрица, из них — SVG.
   Сверено декодером zxing-cpp на наборе строк (work/tests/barcodes-verify.py). */
const EAN_L = ['0001101', '0011001', '0010011', '0111101', '0100011', '0110001', '0101111', '0111011', '0110111', '0001011'];
const EAN_R = EAN_L.map(s => s.replace(/./g, ч => ч === '1' ? '0' : '1'));
const EAN_G = EAN_R.map(s => s.split('').reverse().join(''));
const EAN_ЧЁТНОСТЬ = ['LLLLLL', 'LLGLGG', 'LLGGLG', 'LLGGGL', 'LGLLGG', 'LGGLLG', 'LGGGLL', 'LGLGLG', 'LGLGGL', 'LGGLGL'];
/* контрольная цифра EAN/GTIN: веса 3 и 1 справа налево */
function eanКонтроль(цифры){
  let s = 0;
  for(let i = 0; i < цифры.length; i++) s += +цифры[цифры.length - 1 - i] * (i % 2 ? 1 : 3);
  return (10 - s % 10) % 10;
}
/* EAN-13: 12 цифр — допишем контрольную, 13 — проверим */
function ean13(значение){
  const ц = String(значение).replace(/\s/g, '');
  if(!/^\d{12,13}$/.test(ц)) return {ошибка: 'EAN-13 — это 12 или 13 цифр'};
  const к = eanКонтроль(ц.slice(0, 12));
  if(ц.length === 13 && +ц[12] !== к) return {ошибка: 'неверная контрольная цифра: должна быть ' + к};
  const все = ц.slice(0, 12) + к, п = EAN_ЧЁТНОСТЬ[+все[0]];
  let b = '101';
  for(let i = 1; i <= 6; i++) b += (п[i - 1] === 'L' ? EAN_L : EAN_G)[+все[i]];
  b += '01010';
  for(let i = 7; i <= 12; i++) b += EAN_R[+все[i]];
  b += '101';
  return {полосы: b, текст: все, вид: 'ean13'};
}
function ean8(значение){
  const ц = String(значение).replace(/\s/g, '');
  if(!/^\d{7,8}$/.test(ц)) return {ошибка: 'EAN-8 — это 7 или 8 цифр'};
  const к = eanКонтроль(ц.slice(0, 7));
  if(ц.length === 8 && +ц[7] !== к) return {ошибка: 'неверная контрольная цифра: должна быть ' + к};
  const все = ц.slice(0, 7) + к;
  let b = '101';
  for(let i = 0; i < 4; i++) b += EAN_L[+все[i]];
  b += '01010';
  for(let i = 4; i < 8; i++) b += EAN_R[+все[i]];
  b += '101';
  return {полосы: b, текст: все, вид: 'ean8'};
}
/* Code 128: ширины полос и пробелов для значений 0…106 (106 — «стоп») */
const C128 = ('212222 222122 222221 121223 121322 131222 122213 122312 132212 221213 221312 231212 112232 122132 122231 113222 123122 123221 223211 221132 '
  + '221231 213212 223112 312131 311222 321122 321221 312212 322112 322211 212123 212321 232121 111323 131123 131321 112313 132113 132311 211313 '
  + '231113 231311 112133 112331 132131 113123 113321 133121 313121 211331 231131 213113 213311 213131 311123 311321 331121 312113 312311 332111 '
  + '314111 221411 431111 111224 111422 121124 121421 141122 141221 112214 112412 122114 122411 142112 142211 241211 221114 413111 241112 134111 '
  + '111242 121142 121241 114212 124112 124211 411212 421112 421211 212141 214121 412121 111143 111341 131141 114113 114311 411113 411311 113141 '
  + '114131 311141 411131 211412 211214 211232 2331112').split(' ');
function code128(значение){
  const т = String(значение);
  if(!т.length) return {ошибка: 'пусто'};
  for(const ч of т){ const к = ч.charCodeAt(0); if(к < 32 || к > 126) return {ошибка: 'Code 128 здесь — только латиница, цифры и знаки (без русских букв)'}; }
  /* набор C (пары цифр) — для участков из 4+ цифр (или всей строки из чётного числа цифр), иначе B */
  const коды = [];
  let i = 0, набор = null;
  const цифрВпереди = j => { let n = 0; while(j + n < т.length && /\d/.test(т[j + n])) n++; return n; };
  while(i < т.length){
    const n = цифрВпереди(i);
    const вC = n >= 4 || (n >= 2 && n === т.length - i && набор === 'C') || (i === 0 && n === т.length && n % 2 === 0 && n >= 2);
    if(вC){
      const пар = Math.floor(n / 2);
      if(набор !== 'C'){ коды.push(набор === null ? 105 : 99); набор = 'C'; }
      for(let k = 0; k < пар; k++){ коды.push(+т.substr(i, 2)); i += 2; }
      continue;
    }
    if(набор !== 'B'){ коды.push(набор === null ? 104 : 100); набор = 'B'; }
    коды.push(т.charCodeAt(i) - 32); i++;
  }
  let сумма = коды[0];
  for(let k = 1; k < коды.length; k++) сумма += коды[k] * k;
  коды.push(сумма % 103, 106);
  let b = '';
  for(const к of коды){ const w = C128[к]; for(let j = 0; j < w.length; j++) b += (j % 2 ? '0' : '1').repeat(+w[j]); }
  return {полосы: b, текст: т, вид: 'code128'};
}
/* DataMatrix ECC 200, квадратные символы 10×10 … 52×52, кодирование ASCII (пары цифр — одним кодом).
   GS1 (маркировка): первым идёт FNC1, разделитель групп — символ GS (код 29). */
const DM_РАЗМЕРЫ = [
  /* сторона, данных, контроля, областей на сторону, блоков */
  [10, 3, 5, 1, 1], [12, 5, 7, 1, 1], [14, 8, 10, 1, 1], [16, 12, 12, 1, 1], [18, 18, 14, 1, 1], [20, 22, 18, 1, 1], [22, 30, 20, 1, 1],
  [24, 36, 24, 1, 1], [26, 44, 28, 1, 1], [32, 62, 36, 2, 1], [36, 86, 42, 2, 1], [40, 114, 48, 2, 1], [44, 144, 56, 2, 1], [48, 174, 68, 2, 1],
  [52, 204, 84, 2, 2]];
const DM_ЛОГ = new Uint8Array(256), DM_ЭКСП = new Uint8Array(512);
(function(){ let x = 1; for(let i = 0; i < 255; i++){ DM_ЭКСП[i] = x; DM_ЛОГ[x] = i; x <<= 1; if(x & 0x100) x ^= 0x12D; } for(let i = 255; i < 512; i++) DM_ЭКСП[i] = DM_ЭКСП[i - 255]; })();
const dmУмн = (a, b) => (a && b) ? DM_ЭКСП[DM_ЛОГ[a] + DM_ЛОГ[b]] : 0;
function dmКонтроль(данные, n){
  /* многочлен-генератор с корнями α^1 … α^n */
  let g = [1];
  for(let i = 1; i <= n; i++){ const с = new Array(g.length + 1).fill(0); for(let j = 0; j < g.length; j++){ с[j] ^= g[j]; с[j + 1] ^= dmУмн(g[j], DM_ЭКСП[i]); } g = с; }
  const буф = данные.concat(new Array(n).fill(0));
  for(let i = 0; i < данные.length; i++){ const к = буф[i]; if(!к) continue; for(let j = 0; j < g.length; j++) буф[i + j] ^= dmУмн(g[j], к); }
  return буф.slice(данные.length);
}
function dmКодыASCII(т, gs1){
  const к = [];
  if(gs1) к.push(232);
  for(let i = 0; i < т.length; i++){
    const c = т.charCodeAt(i);
    if(c >= 48 && c <= 57 && i + 1 < т.length && т.charCodeAt(i + 1) >= 48 && т.charCodeAt(i + 1) <= 57){ к.push(130 + (c - 48) * 10 + т.charCodeAt(i + 1) - 48); i++; }
    else if(c < 128) к.push(c + 1);
    else if(c < 256){ к.push(235, c - 127); }
    else return null;
  }
  return к;
}
function dmРазместить(nrow, ncol, кодов){
  const м = new Int8Array(nrow * ncol).fill(-1), что = new Int32Array(nrow * ncol);   /* что: номер кода·16 + бит (1…8) */
  function модуль(r, c, ch, bit){
    if(r < 0){ r += nrow; c += 4 - ((nrow + 4) % 8); }
    if(c < 0){ c += ncol; r += 4 - ((ncol + 4) % 8); }
    м[r * ncol + c] = 1; что[r * ncol + c] = ch * 16 + bit;
  }
  const юта = (r, c, ch) => { модуль(r - 2, c - 2, ch, 1); модуль(r - 2, c - 1, ch, 2); модуль(r - 1, c - 2, ch, 3); модуль(r - 1, c - 1, ch, 4);
    модуль(r - 1, c, ch, 5); модуль(r, c - 2, ch, 6); модуль(r, c - 1, ch, 7); модуль(r, c, ch, 8); };
  const угол1 = ch => { модуль(nrow - 1, 0, ch, 1); модуль(nrow - 1, 1, ch, 2); модуль(nrow - 1, 2, ch, 3); модуль(0, ncol - 2, ch, 4); модуль(0, ncol - 1, ch, 5); модуль(1, ncol - 1, ch, 6); модуль(2, ncol - 1, ch, 7); модуль(3, ncol - 1, ch, 8); };
  const угол2 = ch => { модуль(nrow - 3, 0, ch, 1); модуль(nrow - 2, 0, ch, 2); модуль(nrow - 1, 0, ch, 3); модуль(0, ncol - 4, ch, 4); модуль(0, ncol - 3, ch, 5); модуль(0, ncol - 2, ch, 6); модуль(0, ncol - 1, ch, 7); модуль(1, ncol - 1, ch, 8); };
  const угол3 = ch => { модуль(nrow - 3, 0, ch, 1); модуль(nrow - 2, 0, ch, 2); модуль(nrow - 1, 0, ch, 3); модуль(0, ncol - 2, ch, 4); модуль(0, ncol - 1, ch, 5); модуль(1, ncol - 1, ch, 6); модуль(2, ncol - 1, ch, 7); модуль(3, ncol - 1, ch, 8); };
  const угол4 = ch => { модуль(nrow - 1, 0, ch, 1); модуль(nrow - 1, ncol - 1, ch, 2); модуль(0, ncol - 3, ch, 3); модуль(0, ncol - 2, ch, 4); модуль(0, ncol - 1, ch, 5); модуль(1, ncol - 3, ch, 6); модуль(1, ncol - 2, ch, 7); модуль(1, ncol - 1, ch, 8); };
  let ch = 0, r = 4, c = 0;
  do {
    if(r === nrow && c === 0) угол1(ch++);
    if(r === nrow - 2 && c === 0 && ncol % 4) угол2(ch++);
    if(r === nrow - 2 && c === 0 && ncol % 8 === 4) угол3(ch++);
    if(r === nrow + 4 && c === 2 && !(ncol % 8)) угол4(ch++);
    do { if(r < nrow && c >= 0 && м[r * ncol + c] < 0) юта(r, c, ch++); r -= 2; c += 2; } while(r >= 0 && c < ncol);
    r += 1; c += 3;
    do { if(r >= 0 && c < ncol && м[r * ncol + c] < 0) юта(r, c, ch++); r += 2; c -= 2; } while(r < nrow && c >= 0);
    r += 3; c += 1;
  } while(r < nrow || c < ncol);
  return {м, что};
}
function datamatrix(значение, {gs1 = false} = {}){
  const т = String(значение).replace(/<GS>|\\u001d|␝/gi, '\u001d');
  const данные = dmКодыASCII(т, gs1);
  if(!данные) return {ошибка: 'DataMatrix здесь — только латиница, цифры и знаки'};
  const размер = DM_РАЗМЕРЫ.find(x => x[1] >= данные.length);
  if(!размер) return {ошибка: 'слишком длинно для DataMatrix 52×52 (до 204 кодов)'};
  const [S, nd, nc, k, блоков] = размер;
  /* добивка: 129, затем «псевдослучайные» по номеру позиции */
  const код = данные.slice();
  if(код.length < nd) код.push(129);
  while(код.length < nd){ const поз = код.length + 1; let v = 129 + ((149 * поз) % 253) + 1; if(v > 254) v -= 254; код.push(v); }
  /* контроль по блокам с чередованием */
  const ecc = new Array(nc);
  for(let б = 0; б < блоков; б++){
    const часть = код.filter((x, i) => i % блоков === б);
    const к = dmКонтроль(часть, nc / блоков);
    к.forEach((x, i) => { ecc[i * блоков + б] = x; });
  }
  const все = код.concat(ecc);
  const R = (S - 2 * k) / k, n = R * k;          /* сторона области данных и всей карты */
  const {м, что} = dmРазместить(n, n, все.length);
  const бит = i => { if(м[i] < 0) return 0; const x = что[i], ch = x >> 4, b = x & 15; return (все[ch] >> (8 - b)) & 1; };
  const карта = new Uint8Array(n * n);
  for(let i = 0; i < n * n; i++) карта[i] = бит(i);
  /* нетронутый правый нижний угол 2×2 — по стандарту шахматкой */
  if(м[n * n - 1] < 0){ карта[n * n - 1] = 1; карта[n * n - n - 2] = 1; карта[n * n - 2] = 0; карта[n * n - n - 1] = 0; }
  const матрица = [];
  for(let y = 0; y < S; y++){
    const ряд = [];
    for(let x = 0; x < S; x++){
      const ry = y % (R + 2), rx = x % (R + 2), ly = Math.floor(y / (R + 2)), lx = Math.floor(x / (R + 2));
      let v;
      if(rx === 0) v = 1;
      else if(ry === R + 1) v = 1;
      else if(ry === 0) v = rx % 2 === 0 ? 1 : 0;
      else if(rx === R + 1) v = ry % 2 === 1 ? 1 : 0;
      else v = карта[(ly * R + ry - 1) * n + lx * R + rx - 1];
      ряд.push(v);
    }
    матрица.push(ряд);
  }
  return {матрица, текст: т, вид: 'datamatrix', сторона: S};
}
/* --- SVG --- */
function svgПолосы(р, {высота = 60, цифры = true, цвет = '#000', фон = '#fff'} = {}){
  const тихая = р.вид === 'code128' ? 10 : р.вид === 'ean8' ? 7 : 11;
  const w = р.полосы.length + тихая * 2, текстВыс = цифры ? 11 : 0, h = высота + текстВыс + 2;
  let пути = '';
  let x = 0;
  while(x < р.полосы.length){
    if(р.полосы[x] !== '1'){ x++; continue; }
    let n = 1; while(р.полосы[x + n] === '1') n++;
    /* у EAN защитные полосы длиннее — опускаются в строку цифр */
    let низ = высота;
    if(цифры && (р.вид === 'ean13' || р.вид === 'ean8')){
      const край = р.вид === 'ean13' ? [0, 1, 2, 45, 46, 47, 48, 49, 92, 93, 94] : [0, 1, 2, 31, 32, 33, 34, 35, 64, 65, 66];
      if(край.includes(x)) низ = высота + 6;
    }
    пути += 'M' + (тихая + x) + ' 1h' + n + 'v' + (низ - 1) + 'h-' + n + 'z';
    x += n;
  }
  let подпись = '';
  if(цифры){
    const т = р.текст.replace(/[&<>]/g, s => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'})[s]);
    const у = высота + текстВыс;
    if(р.вид === 'ean13') подпись = '<text x="' + (тихая - 7) + '" y="' + у + '">' + т[0] + '</text><text x="' + (тихая + 3) + '" y="' + у + '" textLength="41">' + т.slice(1, 7) + '</text><text x="' + (тихая + 50) + '" y="' + у + '" textLength="41">' + т.slice(7) + '</text>';
    else if(р.вид === 'ean8') подпись = '<text x="' + (тихая + 3) + '" y="' + у + '" textLength="27">' + т.slice(0, 4) + '</text><text x="' + (тихая + 36) + '" y="' + у + '" textLength="27">' + т.slice(4) + '</text>';
    else подпись = '<text x="' + (w / 2) + '" y="' + у + '" text-anchor="middle">' + т + '</text>';
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + w + ' ' + h + '" shape-rendering="crispEdges">'
    + '<rect width="' + w + '" height="' + h + '" fill="' + фон + '"/><path fill="' + цвет + '" d="' + пути + '"/>'
    + (подпись ? '<g font-family="Arial, sans-serif" font-size="10" fill="' + цвет + '">' + подпись + '</g>' : '') + '</svg>';
}
function svgМатрица(р, {поле = 2, цвет = '#000', фон = '#fff'} = {}){
  const S = р.матрица.length, w = S + поле * 2;
  let пути = '';
  р.матрица.forEach((ряд, y) => { let x = 0; while(x < S){ if(!ряд[x]){ x++; continue; } let n = 1; while(ряд[x + n]) n++; пути += 'M' + (x + поле) + ' ' + (y + поле) + 'h' + n + 'v1h-' + n + 'z'; x += n; } });
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + w + ' ' + w + '" shape-rendering="crispEdges"><rect width="' + w + '" height="' + w + '" fill="' + фон + '"/><path fill="' + цвет + '" d="' + пути + '"/></svg>';
}
function штрихкод(вид, значение, опц){
  if(вид === 'EAN-13') return ean13(значение);
  if(вид === 'EAN-8') return ean8(значение);
  if(вид === 'Code 128') return code128(значение);
  if(вид === 'DataMatrix') return datamatrix(значение, опц || {});
  if(вид === 'DataMatrix GS1') return datamatrix(значение, {gs1: true});
  return {ошибка: 'неизвестный вид'};
}
/* ===== конец штрихкодов ===== */

const ЛИСТЫ = {
  'A4 — 3×8, 70×37 мм':     {стлб: 3, рядов: 8,  w: 70,   h: 37,   сверху: 0.5,  слева: 0},
  'A4 — 3×7, 70×42,3 мм':   {стлб: 3, рядов: 7,  w: 70,   h: 42.3, сверху: 0.45, слева: 0},
  'A4 — 2×8, 105×37 мм':    {стлб: 2, рядов: 8,  w: 105,  h: 37,   сверху: 0.5,  слева: 0},
  'A4 — 2×7, 105×42,3 мм':  {стлб: 2, рядов: 7,  w: 105,  h: 42.3, сверху: 0.45, слева: 0},
  'A4 — 4×10, 52,5×29,7 мм': {стлб: 4, рядов: 10, w: 52.5, h: 29.7, сверху: 0,    слева: 0},
  'A4 — 2×4, 105×74 мм':    {стлб: 2, рядов: 4,  w: 105,  h: 74,   сверху: 0.5,  слева: 0},
};
const ММ = мм => мм / 25.4 * 96;                          /* миллиметры → точки экрана (печать идёт при 96 точках на дюйм) */
const ЗАГОЛОВКИ = {
  название: /^(наименование|название|товар|номенклатура|имя|name)/i,
  цена: /^(цена|стоимость|розница|price)/i,
  код: /^(штрих|ean|gtin|код маркировки|баркод|barcode|код$)/i,
  артикул: /^(артикул|арт\.?|sku|код товара)/i,
  количество: /^(кол-во|кол\.|количество|копий|qty|шт\.?$)/i,
};
const руб = x => typeof x === 'number' ? x.toLocaleString('ru-RU', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' ₽' : String(x || '');

/* картинка кода: SVG и размеры при заданной высоте */
function картинкаКода(вид, значение, {высота, цифры}){
  const р = штрихкод(вид, значение);
  if(р.ошибка) return р;
  if(р.матрица) return {svg: svgМатрица(р), ширина: высота, высота, р};
  const svg = svgПолосы(р, {цифры, высота: 60});
  const м = /viewBox="([\d.]+) ([\d.]+) ([\d.]+) ([\d.]+)"/.exec(svg), vw = +м[3], vh = +м[4];
  /* модуль не тоньше точки: иначе принтер и экран съедят тонкие полосы */
  const ширина = Math.max(Math.round(высота * vw / vh), vw);
  return {svg, ширина, высота: Math.round(ширина * vh / vw), р};
}

/* прежние картинки кодов в области — убрать, чтобы новые не легли поверх */
async function убратьСтарые(r1, c1, r2, c2){
  const список = await картинка.список();
  let n = 0;
  for(const x of список){
    const r = x.строка - 1, c = x.столбец - 1;
    if(r >= r1 && r <= r2 && c >= c1 && c <= c2 && /^(EAN-13|EAN-8|Code 128|DataMatrix)/.test(x.имя || '')){ картинка.убрать(x.id); n++; }
  }
  return n;
}
/* ===== 1. Штрихкоды рядом с клетками ===== */
async function Штрихкоды(){
  const п = параметры({}), в = книга.выделение;
  if(!в || !в.область){ панель.сообщение('Выделите клетки со значениями для штрихкодов.'); return; }
  const вид = п.вид || 'EAN-13', высота = Math.max(24, Math.min(400, +п.высота || 60));
  const строки = await диапазон(ОБЛАСТЬ(в.r1 - 1, в.c1 - 1, в.r2 - 1, в.c1 - 1)).прочитать();
  /* картинки — в первый свободный столбец справа от выделения (с нуля), чтобы не закрыть данные */
  let c = в.c2;
  for(let k = 0; k < 30 && !(await областьПуста(в.r1 - 1, c, в.r2 - 1, c)); k++) c++;
  let сделано = 0, ширинаМакс = 0;
  const ошибки = [];
  await убратьСтарые(в.r1 - 1, c, в.r2 - 1, c);
  строки.forEach((ряд, i) => {
    const v = ряд[0];
    if(v === null || v === undefined || v === '') return;
    const значение = typeof v === 'number' ? (Number.isInteger(v) ? String(v) : String(v)) : String(v).trim();
    const к = картинкаКода(вид, значение, {высота, цифры: п.цифры !== false});
    const адр = АДРЕС(в.r1 - 1 + i, в.c1 - 1);
    if(к.ошибка){ ошибки.push([адр, к.ошибка]); return; }
    картинка.вставить(к.svg, {адрес: АДРЕС(в.r1 - 1 + i, c), сдвигX: 4, сдвигY: 3, ширина: к.ширина, высота: к.высота, имя: вид + ': ' + значение.slice(0, 40)});
    Api.GetActiveSheet().GetRange(ОБЛАСТЬ(в.r1 - 1 + i, c, в.r1 - 1 + i, c)).SetRowHeight((к.высота + 6) * 0.75);
    ширинаМакс = Math.max(ширинаМакс, к.ширина);
    сделано++;
  });
  if(ширинаМакс) Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth((ширинаМакс + 10) / 7);
  await обновитьВысоты();
  панель.список('ошибки', ошибки.length ? ошибки.slice(0, 50) : [['Ошибок нет', '']]);
  панель.сообщение('Штрихкодов ' + вид + ': ' + сделано + ' — в столбце ' + БУКВА(c) + '.' + (ошибки.length ? ' Не получилось: ' + ошибки.length + ' (список ниже).' : ''));
}
/* Из клетки под курсором — пункт меню и кнопка ленты. */
async function ИзКлетки(){
  const п = параметры({}), в = книга.выделение;
  const v = await ячейка(в.строка, в.столбец).прочитать();
  if(v === null || v === undefined || v === ''){ панель.сообщение('В клетке пусто.'); return; }
  const к = картинкаКода(п.вид || 'EAN-13', String(v).trim(), {высота: +п.высота || 60, цифры: п.цифры !== false});
  if(к.ошибка){ панель.сообщение('Не получилось: ' + к.ошибка + '.'); return; }
  картинка.вставить(к.svg, {адрес: АДРЕС(в.строка - 1, в.столбец), ширина: к.ширина, высота: к.высота, имя: (п.вид || 'EAN-13') + ': ' + String(v).slice(0, 40)});
  панель.сообщение('Штрихкод — справа от ' + в.адрес + '.');
}
/* Проверка EAN: контрольные цифры выделенных кодов. */
async function Проверить(){
  const в = книга.выделение;
  if(!в || !в.область){ панель.сообщение('Выделите столбец с кодами.'); return; }
  const строки = await диапазон(в.область).прочитать();
  let верно = 0;
  const плохие = [];
  строки.forEach((ряд, i) => ряд.forEach((v, j) => {
    if(v === null || v === undefined || v === '') return;
    const s = String(v).replace(/\s/g, ''), адр = АДРЕС(в.r1 - 1 + i, в.c1 - 1 + j);
    if(!/^\d+$/.test(s)){ плохие.push([адр, 'не только цифры']); return; }
    if(![8, 12, 13, 14].includes(s.length)){ плохие.push([адр, s.length + ' цифр — это не EAN-8/13 и не GTIN-14']); return; }
    const к = eanКонтроль(s.slice(0, -1));
    if(+s[s.length - 1] !== к && s.length !== 12) плохие.push([адр, 'контрольная цифра должна быть ' + к]);
    else верно++;
  }));
  панель.список('ошибки', плохие.length ? плохие.slice(0, 100) : [['Все коды верны', String(верно)]]);
  панель.сообщение('Проверено: верных ' + верно + ', с ошибками ' + плохие.length + '.');
}

