let взято = null;
async function ВзятьТаблицу(){
  const в = книга.выделение;
  if(!в || !в.область || в.r2 === в.r1){ панель.сообщение('Выделите таблицу товаров вместе со строкой заголовков.'); return; }
  const строки = await диапазон(в.область).прочитать();
  const шапка = (строки[0] || []).map(x => String(x == null ? '' : x).trim());
  const где = {};
  /* каждый столбец — только одному полю */
  const занято = new Set();
  for(const поле of ['код', 'количество', 'цена', 'артикул', 'название']){
    const i = шапка.findIndex((x, j) => !занято.has(j) && ЗАГОЛОВКИ[поле].test(x));
    if(i >= 0){ где[поле] = i; занято.add(i); }
  }
  if(где.название === undefined) где.название = 0;
  const ряды = строки.slice(1).filter(р => р.some(x => x !== null && x !== '')).map(р => ({
    название: р[где.название] == null ? '' : String(р[где.название]), цена: где.цена !== undefined ? р[где.цена] : null,
    код: где.код !== undefined && р[где.код] != null ? String(р[где.код]).trim() : '', артикул: где.артикул !== undefined && р[где.артикул] != null ? String(р[где.артикул]) : '',
    копий: где.количество !== undefined ? Math.max(0, Math.min(500, Math.round(+р[где.количество] || 0))) : 1}));
  взято = {ряды, где, шапка, лист: в.лист};
  хранилище.положить('таблица', взято);
  панель.список('взято', [['Строк', String(ряды.length)]].concat(Object.entries(где).map(([поле, i]) => [поле, '«' + шапка[i] + '» (' + БУКВА(в.c1 - 1 + i) + ')'])));
  панель.сообщение('Взято строк: ' + ряды.length + '. Теперь перейдите на пустой лист (+ внизу), щёлкните A1 и нажмите «Разложить этикетки».');
}
async function Разложить(){
  const п = параметры({});
  if(!взято) взято = хранилище.взять('таблица', null);
  if(!взято || !взято.ряды.length){ панель.сообщение('Сначала выделите таблицу товаров и нажмите «Взять таблицу».'); return; }
  const лист1 = ЛИСТЫ[п.лист] || (п.лист === 'свой размер' ? {стлб: Math.max(1, +п.свСтлб || 3), рядов: Math.max(1, +п.свРядов || 8), w: +п.свШир || 70, h: +п.свВыс || 37, сверху: +п.свСверху || 0, слева: +п.свСлева || 0} : ЛИСТЫ['A4 — 3×8, 70×37 мм']);
  if(книга.выделение && книга.выделение.лист === взято.лист){
    if(!(await диалог.вопрос('Этикетки ложатся на этот же лист, где таблица, и поменяют ширины его столбцов. Лучше — на пустом листе. Всё равно здесь?'))) return;
  }
  const ценник = String(п.шаблон || '').startsWith('ценник');
  const вид = п.вид || 'EAN-13';
  /* этикетки по копиям */
  const список = [];
  for(const р of взято.ряды) for(let k = 0; k < (п.поКоличеству && взято.где.количество !== undefined ? р.копий : Math.max(1, +п.копий || 1)); k++) список.push(р);
  if(!список.length){ панель.сообщение('Нечего печатать: количество везде ноль.'); return; }
  /* сетка: столбец-отступ слева, строка-отступ сверху, на этикетку — 3 строки; между листами — ничего,
     следующий лист начинается со своего отступа */
  const ШИР = ММ(лист1.w), ВЫС = ММ(лист1.h);
  const доли = ценник ? [0.30, 0.32, 0.38] : [0.34, 0.16, 0.50];
  const высоты = доли.map(d => ВЫС * d);
  const на = лист1.стлб * лист1.рядов, листов = Math.ceil(список.length / на);
  const л = Api.GetActiveSheet();
  const есть = await областьПуста(0, 0, листов * (лист1.рядов * 3 + 1), лист1.стлб);
  if(!есть && !(await диалог.вопрос('На листе уже что-то есть — этикетки лягут поверх. Продолжить?'))) return;
  /* размеры — целыми точками, но без накопления ошибки: границы считаются от начала листа */
  const целые = (старт, шаги) => { const out = []; let x = старт; for(const ш of шаги){ out.push(Math.round(x + ш) - Math.round(x)); x += ш; } return out; };
  const ширины = целые(ММ(лист1.слева), new Array(лист1.стлб).fill(ШИР));
  л.GetRange(ОБЛАСТЬ(0, 0, 0, 0)).SetColumnWidth(Math.max(1, Math.round(ММ(лист1.слева))) / 7);
  ширины.forEach((ш, j) => л.GetRange(ОБЛАСТЬ(0, 1 + j, 0, 1 + j)).SetColumnWidth(ш / 7));
  const шагиСтраницы = []; for(let k = 0; k < лист1.рядов; k++) шагиСтраницы.push(...высоты);
  const высотыСтраницы = целые(ММ(лист1.сверху), шагиСтраницы);
  /* высоты строк — сразу на все страницы целиком, даже если последняя заполнена не до конца */
  for(let лист2 = 0; лист2 < листов; лист2++){
    const r00 = лист2 * (лист1.рядов * 3 + 1);
    высотаСтроки(r00, Math.max(1, Math.round(ММ(лист1.сверху))));
    высотыСтраницы.forEach((в, k) => высотаСтроки(r00 + 1 + k, в));
  }
  await обновитьВысоты();
  const РАМ = {вид: 'пунктир', цвет: '#c5ccd8'};
  /* прошлая раскладка: картинки и клетки страниц — начисто */
  await убратьСтарые(0, 0, листов * (лист1.рядов * 3 + 1), лист1.стлб);
  for(let r = 0; r < листов * (лист1.рядов * 3 + 1); r++) for(let j = 1; j <= лист1.стлб; j++){ const к = клетка(r, j); к.значение = ''; к.стиль = {гр: РАМКА('нет'), b: 0, size: null}; }
  let ошибок = 0;
  for(let n = 0; n < список.length; n++){
    const лист2 = Math.floor(n / на), m = n % на, ряд = Math.floor(m / лист1.стлб), стлб = m % лист1.стлб;
    const r0 = лист2 * (лист1.рядов * 3 + 1) + 1 + ряд * 3, c0 = 1 + стлб;
    const т = список[n];
    const верх = клетка(r0, c0), середина = клетка(r0 + 1, c0), низ = клетка(r0 + 2, c0);
    верх.значение = т.название;
    верх.стиль = {wrap: 1, b: 1, size: ценник ? 10 : 9, align: 'center', valign: 'middle', гр: {в: РАМ, л: РАМ, п: РАМ}};
    if(ценник){ середина.значение = т.цена == null ? '' : руб(т.цена); середина.стиль = {b: 1, size: 20, align: 'center', valign: 'middle', гр: {л: РАМ, п: РАМ}}; }
    else { середина.значение = [т.артикул ? 'Арт. ' + т.артикул : '', т.цена != null && т.цена !== '' ? руб(т.цена) : ''].filter(Boolean).join(' · '); середина.стиль = {size: 9, align: 'center', valign: 'middle', гр: {л: РАМ, п: РАМ}}; }
    низ.значение = ''; низ.стиль = {гр: {н: РАМ, л: РАМ, п: РАМ}};
    if(т.код){
      const выс = Math.max(20, высоты[2] - 6);
      const к = картинкаКода(вид, т.код, {высота: выс, цифры: true});
      if(к.ошибка){ ошибок++; низ.значение = т.код + ' — ' + к.ошибка; низ.стиль = {size: 7, color: '#dc2626', wrap: 1, align: 'center'}; }
      else {
        /* картинка на всю клетку — SVG сам встанет по центру, пропорции сохранятся */
        картинка.вставить(к.svg, {адрес: АДРЕС(r0 + 2, c0), сдвигX: 4, сдвигY: 3, ширина: Math.round(ШИР - 8), высота: Math.round(выс), имя: вид + ': ' + т.код});
      }
    }
  }
  /* параметры печати листа: A4, книжная, 100%, без полей, сетки и названия */
  лист().запомнить('печать', {область: null, шапка: 0, ориентация: 'portrait', бумага: 'A4', уместить: false, масштаб: 100, сетка: false, заголовки: false, название: false, поле: 0});
  наСтоянку(0, 0);
  панель.сообщение('Этикеток: ' + список.length + ' на ' + листов + ' лист(ах) ' + (п.лист || '') + '.' + (ошибок ? ' Коды с ошибкой: ' + ошибок + ' — отмечены красным.' : '')
    + ' Печать уже настроена: A4, 100%, без полей. Сначала проверьте на простой бумаге, приложив к листу наклеек.');
}
